import React from "react";
import Video from "../../Video/Video";

function SectionComopnent({ title, video, para }) {
  return (
    <div className=" relative top-5">
      <div className=" ">
        <Video video={video} />
        <div className="">
          <h1 className=" text-4xl text-center m-5 text-yellow-400">{title}</h1>
          <p>{para}</p>
        </div>
      </div>
    </div>
  );
}

export default SectionComopnent;
